begin;
drop function if exists public.record_workforce_time_event(uuid,uuid,text,uuid,uuid,text,jsonb);
create function public.record_workforce_time_event(p_company_id uuid,p_employee_id uuid,p_action text,p_project_id uuid default null,p_assignment_id uuid default null,p_notes text default null,p_location jsonb default null,p_break_minutes integer default 0) returns public.workforce_time_entries language plpgsql security invoker set search_path=public as $$ declare v_entry public.workforce_time_entries;begin if p_action not in('clock_in','clock_out')then raise exception 'Unsupported time event';end if;if p_break_minutes<0 or p_break_minutes>1440 then raise exception 'Invalid break minutes';end if;if p_location is not null and(jsonb_typeof(p_location)<>'object'or not(p_location?'latitude'and p_location?'longitude'and p_location?'accuracy'))then raise exception 'Invalid location evidence';end if;if not(exists(select 1 from public.employees e where e.id=p_employee_id and e.company_id=p_company_id and e.profile_id=auth.uid())or public.has_company_role(p_company_id,array['owner','administrator','operations_manager','project_manager','superintendent','foreman','office_manager']))then raise exception 'Not authorized';end if;if p_action='clock_in'then insert into public.workforce_time_entries(company_id,employee_id,project_id,assignment_id,started_at,status,source,notes,created_by,clock_in_location)values(p_company_id,p_employee_id,p_project_id,p_assignment_id,now(),'open','mobile',nullif(btrim(p_notes),''),auth.uid(),p_location)returning * into v_entry;else update public.workforce_time_entries set ended_at=now(),break_minutes=p_break_minutes,status='submitted',notes=coalesce(nullif(btrim(p_notes),''),notes),clock_out_location=p_location,updated_at=now()where company_id=p_company_id and employee_id=p_employee_id and status='open'returning * into v_entry;if v_entry.id is null then raise exception 'No open time entry';end if;end if;return v_entry;end $$;
grant execute on function public.record_workforce_time_event(uuid,uuid,text,uuid,uuid,text,jsonb,integer) to authenticated;
commit;
